// writeThresholds 把 thresholdsPath 指向一个含 contents 的临时文件，测试结束自动恢复。
func writeThresholds(t *testing.T, contents string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(contents), 0o600); err != nil {
		t.Fatalf("写临时阈值配置失败: %v", err)
	}
	old := thresholdsPath
	thresholdsPath = path
	t.Cleanup(func() { thresholdsPath = old })
}

func TestConfiguredWarehouseUsesItsThreshold(t *testing.T) {
	writeThresholds(t, `{"xian": 2}`)
	if got := LowStockThreshold("xian"); got != 2 {
		t.Fatalf("LowStockThreshold(\"xian\") = %d, 期望配置值 2", got)
	}
}

func TestUnconfiguredWarehouseInConfigFileFallsBack(t *testing.T) {
	writeThresholds(t, `{"xian": 2}`)
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("配置里没有的仓库应当回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMissingThresholdsFileFallsBack(t *testing.T) {
	old := thresholdsPath
	thresholdsPath = filepath.Join(t.TempDir(), "missing.json")
	t.Cleanup(func() { thresholdsPath = old })
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时应当回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMalformedThresholdsFallsBack(t *testing.T) {
	writeThresholds(t, `{"xian": `)
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置不是合法 JSON 时应当回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestNonObjectThresholdsFallsBack(t *testing.T) {
	writeThresholds(t, `[1, 2, 3]`)
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("配置不是 JSON 对象时应当回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestShippedThresholdsConfigIsRead(t *testing.T) {
	// 不覆盖 thresholdsPath：验证仓库根的 config/thresholds.json 确实被读到。
	if got := LowStockThreshold("xian"); got != 2 {
		t.Fatalf("config/thresholds.json 中 xian 的阈值应为 2，得到 %d", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("chengdu 未配置，应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

